"""Labels for the 2010 -> 2017 edition pair: the 2000 Code 5th edition (2013), 6th edition (2015/16) and the new 2017 Code (in force
1 October 2017). Evidence: MCC 2017 preface (S02: guiding objectives, gender-neutral drafting, 'a new Code was necessary to rationalise
these amendments and to list the Laws in a more logical format and order'); MCC 2013 explanation with reasons (S03); NZC/BOP 2017
summary (S05); news summary quoting MCC (S06); Kent CCC on the 2013 'Finn' law (S07)."""
from _h import make
PAIR = "2010_2017"
L, LABELS = make(PAIR)
ST, UN, NC, EN, NE, EF = "STRUCTURAL", "UNCATEGORISED", "NOT_A_CHANGE", "ENJOYMENT", "NOVEL_EVENT", "EXTERNAL_FORCE"
D17 = "2017 Code, in force 1 October 2017 (S02)."
D13 = "2000 Code 5th edition, effective 1 October 2013 (S03)."
RE = ("MCC: 'The game had evolved quickly, requiring six Editions of the 2000 Code to be published in only fifteen years. A new Code was necessary "
      "to rationalise these amendments and to list the Laws in a more logical format and order' (preface, S02).")
GN = ("MCC: 'for the first time in 2017, the Laws were written in a gender-neutral format, reflecting, and further encouraging, the rising popularity "
      "of the game amongst women and girls' (preface, S02).")


def reorg(eid, what, extra="", sec="", secsub="", note=""):
    L(eid, what, ST, "reorganisation", "medium", "inferred", RE + (" " + extra if extra else ""), ["S02"], date=D17, sec=sec, secsub=secsub, note=note)


def conseq(eid, what, extra="", note=""):
    L(eid, what, ST, "consequential", "medium", "inferred", RE + " Cross-references and sub-clause numbers follow the new numbering." + (" " + extra if extra else ""), ["S02"], date=D17, note=note)


def gn(eid, what, extra="", sec="", secsub="", note=""):
    L(eid, what, EF, "legal_social", "high", "stated", GN + (" " + extra if extra else ""), ["S02"], date=D17, sec=sec, secsub=secsub, note=note)


def pol(eid, what, ev=None, date=D17, note="", sec=ST, secsub="reorganisation", why="A substantive amendment between the 2010 and 2017 texts (2013 and 2015/16 editions or the 2017 Code); no source found states a reason."):
    L(eid, what, UN, "no_cause_stated", "low", "none", why, ev or ["S02"], date=date, sec=sec, secsub=secsub, note=note)


def art(eid, what, why, sub="segmentation_artefact", ev=None, conf="medium", integrity="ok"):
    L(eid, what, NC, sub, conf, "derived", why, ev or ["S18"], integrity=integrity)


