reorg("E086", "Law 41 (Unfair play): 'The captains are responsible for ensuring that play is conducted within The Spirit of Cricket, as described in the Preamble' replaces 'The responsibility lies with the captains ... and traditions of the game'.", sec=EN, secsub="fairness_spirit")
